/**
 * Game server control panel — SSH/RCON transport + per-family control facts.
 *
 * A plain server-side module (NO "use server", no client imports). Imported by
 * BOTH the server actions (lib/actions-game-control.ts) and the worker
 * (worker/game-control.ts). It NEVER runs in the browser — the customer's root
 * credentials and their server's RCON password stay on our server.
 *
 * Everything here operates on the CUSTOMER'S OWN game VM over the platform's
 * existing SSH (host/port/root-password derived exactly like lib/sftp.ts, reused
 * via lib/ssh-exec.ts `withServerSsh`). Two transport rules, mirroring the rest of
 * the control panel:
 *
 *   1. STRICT ALLOWLIST VALIDATION for anything that reaches a shell. Ports, unit
 *      names, paths and file names are validated/allowlisted or rejected — never
 *      sanitized. Family/unit hints are compile-time constants, never customer
 *      input.
 *
 *   2. RCON never touches a shell at all. We read the server's RCON port/password
 *      out of its own config file, then open a TCP channel to 127.0.0.1:<port> on
 *      the game VM THROUGH the SSH connection (`conn.forwardOut`) and speak the
 *      Source RCON wire protocol directly. The RCON port is never exposed off the
 *      box, the password is only ever a protocol packet body (not an argv token),
 *      and the customer's console command is validated to be single-line/control-
 *      char-free before it is sent.
 *
 * SANDBOX: callers gate real SSH behind `!SANDBOX`; on staging the inline reads
 * return realistic synthetic data so the whole UX works without a live VM.
 */
import type { Duplex } from "node:stream";
import type { Client } from "ssh2";
import { GAME_FAMILIES, type GameFamily } from "./games";
import { exec, QUICK_TIMEOUT_MS } from "./ssh-exec";

// ---------------------------------------------------------------------------
// Per-family control facts
// ---------------------------------------------------------------------------

/** How (if at all) we can talk to a running server's console remotely. */
export type RconProtocol =
  | "source" // Valve Source RCON (Minecraft, CS2, Palworld) — implemented here
  | "rust-web" // Rust WebSocket RCON — different protocol, deferred
  | "none"; // no remote console protocol (Valheim/Terraria vanilla)

/**
 * Where a family stores the RCON credentials, and how to read them.
 *
 * Two sources, discriminated by `source`:
 *  - "file": read a config file on the guest (minecraft/cs2/palworld — the
 *    password is written into a config file the game itself reads).
 *  - "docker-env": read the docker CONTAINER's own `--name`d process env via
 *    `docker inspect` (ark/arkasa/tf2/l4d2/projectzomboid). Verified live
 *    2026-09-24 (see the per-family research this session ran against each
 *    image's real Dockerfile/entrypoint) that this is not just simpler but,
 *    for ARK and ARK: Survival Ascended, the ONLY option: `hermsi/ark-server`
 *    converts `ADMIN_PASSWORD` into an `ark_ServerAdminPassword=` arkmanager
 *    key that becomes an unrecorded ShooterGameServer launch argument — it is
 *    never written to GameUserSettings.ini on disk, so a file-based reader
 *    could never find it no matter what path it searched. The other three
 *    families (tf2/l4d2/projectzomboid) do also persist their password to a
 *    file, but "docker-env" is used uniformly for all five: it is sourced
 *    straight from each family's own `docker run -e ...` in prisma/seed-wave*
 *    (the real setup script, not a guessed on-disk path), and matches the
 *    single already-published RCON port that image's `-p` mapping exposes.
 */
type FileRconConfig = {
  source: "file";
  /** Config-file path candidates to try first (absolute). */
  candidates: string[];
  /** Roots to bounded-`find` under if none of the candidates exist. */
  findRoots: string[];
  /** File name to find. */
  findName: string;
  /** File format. */
  kind: "properties" | "palworld-ini";
  /** Key that gates RCON being on (value compared case-insensitively to true/1). */
  enableKey?: string;
  /** Key holding the RCON password. */
  passwordKey: string;
  /** Key holding the RCON port (falls back to `defaultPort`). */
  portKey?: string;
  /** Port used when the file does not specify one. */
  defaultPort: number;
};

type DockerEnvRconConfig = {
  source: "docker-env";
  /** The container's own `--name` from its `docker run` invocation (compile-time
   *  constant, sourced from the family's real setupScript in prisma/seed-wave*.ts —
   *  never guessed). */
  containerName: string;
  /** The docker `-e KEY=...` env var name the setup script sets the RCON/admin
   *  password from (compile-time constant, same provenance as above). */
  passwordEnvKey: string;
  /** Fixed RCON port this family's image publishes (compile-time constant, from
   *  the real `-p` mapping — see GAME_JOIN_PORT_OVERRIDE in lib/games.ts, which
   *  documents the same port for the same reason). */
  port: number;
};

type RconConfig = FileRconConfig | DockerEnvRconConfig;

export type GameControlSpec = {
  family: GameFamily;
  label: string;
  /** systemd unit-name hints (first that resolves wins). Compile-time constants. */
  serviceHints: string[];
  /** Directory candidates that hold the world/save data (for listing + backup). */
  dataRoots: string[];
  /** Remote console protocol. */
  rcon: RconProtocol;
  /** Where/how to read RCON creds (present only when rcon === "source"). */
  rconConfig?: RconConfig;
  /** RCON verb that lists connected players (present when supported). */
  listCommand?: string;
  /** RCON verb template for kicking a player (`%s` = validated name/id). */
  kickCommand?: string;
  /** RCON verb template for banning a player (`%s` = validated name/id). */
  banCommand?: string;
  /**
   * Override for GAME_POWER's post-start port-bind check (worker/game-control.ts's
   * GAME_POWER_PORT_CHECK_TIMEOUT_MS, 30s default). Most families' game process
   * binds its port within a few seconds of systemd reporting the unit active, so
   * 30s is deliberately short — but a family whose own boot legitimately takes
   * longer (world loading, not just process startup) needs real headroom here,
   * or a perfectly healthy start gets reported as a failure. Undefined = use the
   * 30s default.
   */
  powerStartTimeoutMs?: number;
};

/**
 * The control facts per game family.
 *
 * RCON reality (why not every "has RCON" game gets a wire here):
 *  - minecraft: native Source RCON (enable-rcon / rcon.password / rcon.port), read from a config file.
 *  - cs2:       native Source RCON (rcon_password; port defaults to the game port), read from a config file.
 *  - palworld:  native RCON, Source-protocol framing (RCONEnabled/RCONPort/AdminPassword), read from a config file.
 *  - ark, arkasa, tf2, l4d2, projectzomboid: native Source RCON, each verified
 *    2026-09-24 against the platform's real docker image/entrypoint (see each
 *    entry's own comment) — read from the docker CONTAINER's own env
 *    (`source: "docker-env"`), not a file: ARK/ARK:ASA never write the
 *    password to disk at all (arkmanager launch-arg only), and reading all
 *    five the same way avoids guessing at five different community images'
 *    on-disk config layouts.
 *  - rust:      RCON is WebSocket (rcon.web) — a DIFFERENT protocol; deferred.
 *  - squad:     genuine Source RCON exists, but this platform's image ships it
 *    DISABLED (no password ever configured) — a provisioning gap, not a
 *    protocol gap; see squad's own comment below.
 *  - kf2:       has a real remote admin surface (WebAdmin), but it's HTTP, not
 *    the Source RCON binary wire this file speaks — different transport, out
 *    of scope this pass.
 *  - valheim:   no native RCON (needs a BepInEx mod) — console disabled.
 *  - terraria:  vanilla has only a local stdin console — console disabled.
 *  - nightingale, spaceengineers, barotrauma, sandstorm, dst, vintagestory,
 *    necesse, soulmask, and every other family not listed above: no confirmed
 *    Source-RCON wire (soulmask's is confirmed DEAD — loopback-bound inside
 *    its own container, see its comment below) — genuinely "none", not a gap
 *    left unresearched by default assumption.
 */

