          // Field rules (minLength / notInsideField) — shared with the wizard's inline checks.
          const ruleErr = fieldRuleError(field, v, schema.fields, { ...input, ...out });
          if (ruleErr) return { ok: false, error: ruleErr };
        }
        {
          // String-field pattern/length rules (e.g. Valheim SERVER_NAME).
          const nameErr = stringFieldError(field, v);
          if (nameErr) return { ok: false, error: nameErr };
        }
        // CONFIG INJECTION: these values are written verbatim into LINE-ORIENTED
        // files on the customer's VM by worker/game-config.ts —
        // `server.properties` (`motd=<value>`), Rust's `server.cfg`
        // (`server.hostname "<value>"`) and Valheim's launch-args file. A newline
        // therefore does not set one option, it appends arbitrary further
        // options: a motd of "hi\nenable-rcon=true\nrcon.password=x" turns RCON
        // on with a chosen password, and that password is then read back out of
        // the same file and interpolated into an `mcrcon` command line.
        // `enum`/`int`/`bool` are constrained by their own branches; `string` was
