/**
 * Load the current customization state for an owned game server: the resolved
 * family + its schema, the selected variant (defaulting to the schema default)
 * and the stored settings values (validated/normalised against the schema so the
 * UI always gets a complete, well-typed object).
 */
export async function getGameConfig(
  serverId: string
): Promise<{ error?: string; config?: GameConfigView }> {
  const { server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  const variant =
    server.gameVariant && isValidVariant(family, server.gameVariant)
      ? server.gameVariant
      : schema.defaultVariant;

  const validated = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
  const values = validated.ok ? validated.values : {};

  return { config: { family, schema, variant, values } };
}

/**
 * Validate and persist a server's game variant + settings, then enqueue a
 * GAME_CONFIG job to apply them. Refuses while another job is in flight.
 */
export async function saveGameConfig(
  serverId: string,
  variant: string,
  values: Record<string, unknown>,
  opts?: { restart?: boolean }
): Promise<{ error?: string; ok?: boolean; changed?: number; restart?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  if (!isValidVariant(family, variant)) {
    return { error: "Pick a valid server type for this game." };
  }

  const validated = validateConfig(family, values);
  if (!validated.ok) return { error: validated.error };

  // Minecraft: only type × version combinations that actually exist (lib/mcjars/availability.ts).
  if (family === "minecraft") {
    const combo = await checkMinecraftCombo(variant, String(validated.values.VERSION ?? "1.21.1"));
    if (!combo.ok) return { error: combo.message };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // KEEP the platform's own `_`-prefixed markers. This used to write
  // `validated.values` over the whole blob, which silently erased
  // `_serviceState` (GAME_POWER's record that the customer stopped the game) —
  // half of why the 2026-09-30 tomatikk dashboard flipped back to "Online"
  // over a stopped game the moment its owner saved a setting.
  const previous = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const markers = Object.fromEntries(Object.entries(previous).filter(([k]) => k.startsWith("_")));
  const prevValid = validateConfig(family, previous);
  const prevValues = prevValid.ok ? prevValid.values : {};
  const changed = Object.keys(validated.values).filter((k) => prevValues[k] !== validated.values[k]);
  if ((server.gameVariant ?? schema.defaultVariant) !== variant) changed.push("variant");
  const restart = opts?.restart === true;

  await db.server.update({
    where: { id: server.id },
    data: { gameVariant: variant, gameConfig: { ...markers, ...validated.values } as any },
  });
  await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id, payload: { restart, changed, source: "customer" } } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.config",
      detail: `${serverId} family=${family} variant=${variant} changed=${changed.join(",") || "none"}${restart ? " restart=yes" : ""}`,
    },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, changed: changed.length, restart };
}

