  // build 35245 ("recommended" on 2026-10-01), 70,603,408 bytes
  "35245": "16fcffd53a30a3909cbb2cfd26f89f950a59452792cafd0eda2174bdfeef9b2f",
};

export type ChangelogInfo = {
  build: string;
  url: string;
  txadmin: string | null;
};

/** Parse the official changelog JSON for one channel; null if it is not the shape we expect. */
export function parseChangelog(json: unknown, channel: FivemChannel): ChangelogInfo | null {
  if (!json || typeof json !== "object") return null;
  const j = json as Record<string, unknown>;
  const build = j[channel];
