// ---------------------------------------------------------------------------
// Settings → server.cfg
// ---------------------------------------------------------------------------

export const FIVEM_LOCALES = ["en-US", "en-GB", "de-DE", "fr-FR", "es-ES", "pt-BR", "nl-NL", "pl-PL", "it-IT", "tr-TR", "ru-RU", "sv-SE", "da-DK", "nb-NO", "fi-FI", "cs-CZ", "ro-RO", "ar-AE", "zh-CN", "ja-JP", "ko-KR"] as const;

/** The game builds FXServer can enforce (sv_enforceGameBuild). "" = server default. */
export const FIVEM_GAME_BUILDS = ["", "2189", "2372", "2545", "2612", "2699", "2802", "2944", "3095", "3258", "3407", "3570"] as const;

/** Resource names: the same shell/cfg-inert token FXServer resource folders use. */
export const FIVEM_RESOURCE_RE = /^[A-Za-z0-9_-]{1,64}$/;
/** The resources an FXServer needs for a playable vanilla-ish server (from cfx-server-data). */
export const FIVEM_DEFAULT_RESOURCES = ["mapmanager", "chat", "spawnmanager", "sessionmanager", "basic-gamemode", "hardcap"];

export type FivemSettings = {
  sv_hostname: string;
  projectName: string;
  projectDesc: string;
  sv_maxclients: number;
  licenceTier: FivemLicenceTier;
  onesync: FivemOneSync;
  gameBuild: string;
  locale: string;
  tags: string;
  sv_password: string;
  steamWebApiKey: string;
  txadmin: boolean;
  resources: string;
  artifactChannel: FivemChannel;
  artifactBuild: string;
};

export const FIVEM_DEFAULTS: FivemSettings = {
  sv_hostname: "Nxeon FiveM Server",
  projectName: "",
  projectDesc: "",
  sv_maxclients: 32,
  licenceTier: "default",
  onesync: "on",
  gameBuild: "",
  locale: "en-US",
  tags: "default",
  sv_password: "",
  steamWebApiKey: "",
  txadmin: false,
  resources: FIVEM_DEFAULT_RESOURCES.join(","),
  artifactChannel: "recommended",
  artifactBuild: "",
};

/** Coerce a validated gameConfig blob into typed settings (unknown/missing → defaults). */
export function fivemSettingsFrom(values: Record<string, unknown> | null | undefined): FivemSettings {
  const v = values ?? {};
  const s = (k: keyof FivemSettings) => (v[k] === undefined || v[k] === null ? FIVEM_DEFAULTS[k] : v[k]);
  const tier = String(s("licenceTier"));
  const os = String(s("onesync"));
  const ch = String(s("artifactChannel"));
  return {
    sv_hostname: String(s("sv_hostname")),
    projectName: String(s("projectName")),
    projectDesc: String(s("projectDesc")),
    sv_maxclients: Math.trunc(Number(s("sv_maxclients"))) || FIVEM_DEFAULTS.sv_maxclients,
    licenceTier: (["default", "argentum", "aurum", "platinum"].includes(tier) ? tier : "default") as FivemLicenceTier,
    onesync: (["on", "legacy", "off"].includes(os) ? os : "on") as FivemOneSync,
    gameBuild: (FIVEM_GAME_BUILDS as readonly string[]).includes(String(s("gameBuild"))) ? String(s("gameBuild")) : "",
    locale: (FIVEM_LOCALES as readonly string[]).includes(String(s("locale"))) ? String(s("locale")) : "en-US",
    tags: String(s("tags")),
    sv_password: String(s("sv_password")),
    steamWebApiKey: String(s("steamWebApiKey")),
    txadmin: v.txadmin === true || v.txadmin === "true",
    resources: String(s("resources")),
    artifactChannel: (FIVEM_CHANNELS as string[]).includes(ch) ? (ch as FivemChannel) : "recommended",
    artifactBuild: /^\d{3,6}$/.test(String(s("artifactBuild"))) ? String(s("artifactBuild")) : "",
  };
}

/** Parse the comma/space separated resource list; returns the clean names or an error. */
export function parseResourceList(raw: string): { ok: true; names: string[] } | { ok: false; error: string } {
  const names = String(raw ?? "")
    .split(/[\s,]+/)
    .map((x) => x.trim())
    .filter(Boolean);
  if (names.length > 200) return { ok: false, error: "Too many resources (max 200)." };
  const seen = new Set<string>();
  for (const n of names) {
    if (!FIVEM_RESOURCE_RE.test(n)) return { ok: false, error: `"${n.slice(0, 40)}" is not a valid resource folder name (letters, digits, _ and - only).` };
    seen.add(n);
  }
  return { ok: true, names: [...seen] };
}

/** Tags: FXServer's `sets tags "a, b"`. Same inert token set, max 16. */
export function parseTags(raw: string): string[] {
  return String(raw ?? "")
    .split(",")
    .map((t) => t.trim())
    .filter((t) => /^[A-Za-z0-9 _-]{1,24}$/.test(t))
    .slice(0, 16);
}

/**
 * Quote a value for server.cfg. FXServer's console parser treats `"` as the
 * only quote and has no escape for it, so a value containing `"` (or any
 * control char / `;` which ends a command) is not representable — those chars
 * are dropped rather than escaped. validateConfig has already rejected control
 * chars; this is the second, cfg-specific line of defence.
 */
export function cfgQuote(v: string): string {
  // eslint-disable-next-line no-control-regex
  return `"${String(v).replace(/["\x00-\x1f\x7f;]/g, "").slice(0, 256)}"`;
}

/**
 * Render server.cfg. Secrets are NOT in this file: the licence key, RCON
 * password and players token live in `secrets.cfg` (mode 0600, see
 * renderSecretsCfg) which this file `exec`s, so a customer sharing their
 * server.cfg on a forum (common) never leaks their key.
 */
export function renderServerCfg(settings: FivemSettings, opts: { planSlots?: number | null } = {}): string {
  const cap = effectiveSlotCap(opts.planSlots ?? null, settings.licenceTier, settings.onesync);
  const maxClients = Math.max(1, Math.min(settings.sv_maxclients, cap));
  const res = parseResourceList(settings.resources);
  const resources = res.ok ? res.names : FIVEM_DEFAULT_RESOURCES;
  const tags = parseTags(settings.tags);
  const lines: string[] = [
    "# Generated by Nxeon from your server Settings — edits here are overwritten when settings are saved.",
    "# Put your own extra config in custom.cfg (exec'd at the end, never overwritten).",
    `endpoint_add_tcp "0.0.0.0:${FIVEM_GAME_PORT}"`,
    `endpoint_add_udp "0.0.0.0:${FIVEM_GAME_PORT}"`,
    "",
    ...resources.map((r) => `ensure ${r}`),
    "",
    `sv_hostname ${cfgQuote(settings.sv_hostname || FIVEM_DEFAULTS.sv_hostname)}`,
    ...(settings.projectName ? [`sets sv_projectName ${cfgQuote(settings.projectName)}`] : []),
    ...(settings.projectDesc ? [`sets sv_projectDesc ${cfgQuote(settings.projectDesc)}`] : []),
    `sets locale ${cfgQuote(settings.locale)}`,
    ...(tags.length ? [`sets tags ${cfgQuote(tags.join(", "))}`] : []),
    `sv_maxclients ${maxClients}`,
    `set onesync ${settings.onesync}`,
    ...(settings.gameBuild ? [`sv_enforceGameBuild ${settings.gameBuild}`] : []),
    ...(settings.sv_password ? [`sv_password ${cfgQuote(settings.sv_password)}`] : []),
    `set steam_webApiKey ${cfgQuote(settings.steamWebApiKey || "none")}`,
    "sv_scriptHookAllowed 0",
    // Keep the public HTTP endpoints answering server browsers + our probe, but
    // never hand player names/identifiers to anonymous callers — FXServer only
    // returns them on /players.json with the token from secrets.cfg.
    "set sv_requestParanoia 0",
    "",
    "exec secrets.cfg",
    "exec custom.cfg",
    "",
  ];
  return lines.join("\n");
}

/** The 0600 secrets file. Values are allowlisted before they get here. */
export function renderSecretsCfg(secrets: { licenseKey: string | null; rconPassword: string; playersToken: string }): string {
  const lines = ["# Nxeon-managed secrets — do not share this file."];
  if (secrets.licenseKey && isValidLicenseKey(secrets.licenseKey)) lines.push(`sv_licenseKey "${secrets.licenseKey}"`);
  if (/^[A-Za-z0-9]{12,64}$/.test(secrets.rconPassword)) lines.push(`rcon_password "${secrets.rconPassword}"`);
  if (/^[A-Za-z0-9]{16,64}$/.test(secrets.playersToken)) lines.push(`set sv_playersToken "${secrets.playersToken}"`);
  return lines.join("\n") + "\n";
}

/**
 * The runtime env file the container's start script sources. Only integers
 * and fixed tokens — nothing customer-typed reaches it.
 */
export function renderRuntimeEnv(settings: FivemSettings, opts: { planSlots?: number | null } = {}): string {
  const cap = effectiveSlotCap(opts.planSlots ?? null, settings.licenceTier, settings.onesync);
  return [
    `NX_TXADMIN=${settings.txadmin ? "1" : "0"}`,
    `TXHOST_MAX_SLOTS=${cap}`,
    "",
  ].join("\n");
}

/** Artifact selection file the installer/updater reads. */
export function renderArtifactPin(settings: FivemSettings): string {
  return [`NX_FIVEM_CHANNEL=${settings.artifactChannel}`, `NX_FIVEM_BUILD=${settings.artifactBuild}`, ""].join("\n");
}

// ---------------------------------------------------------------------------
// Probes: /info.json, /players.json, txAdmin PIN
// ---------------------------------------------------------------------------

export type FivemInfo = {
  server: string;
  build: string | null;
  maxClients: number | null;
  hostname: string | null;
  resources: number;
  onesync: string | null;
};

/** Parse FXServer's /info.json. Null if it is not an FXServer answer. */
export function parseInfoJson(body: unknown): FivemInfo | null {
  let j: unknown = body;
  if (typeof body === "string") {
    try {
      j = JSON.parse(body);
    } catch {
      return null;
    }
  }
  if (!j || typeof j !== "object") return null;
  const o = j as Record<string, unknown>;
  const server = typeof o.server === "string" ? o.server : null;
  if (!server || !/FXServer/i.test(server)) return null;
  const vars = (o.vars && typeof o.vars === "object" ? o.vars : {}) as Record<string, unknown>;
  const build = /v1\.0\.0\.(\d+)/.exec(server)?.[1] ?? null;
  const mc = Number(vars.sv_maxClients);
  return {
    server,
    build,
    maxClients: Number.isFinite(mc) && mc > 0 ? mc : null,
    hostname: typeof vars.sv_projectName === "string" ? vars.sv_projectName : null,
    resources: Array.isArray(o.resources) ? o.resources.length : 0,
    onesync: typeof vars.onesync_enabled === "string" ? vars.onesync_enabled : null,
  };
}

export type FivemPlayer = { id: number | null; name: string | null; ping: number | null };

/**
 * Parse /players.json. Anonymous callers get entries without names on current
 * builds (the server's own message: "Player names and identifiers are only
 * exposed on /players.json when the request is authenticated via
 * sv_playersToken") — so `name` may be null and the COUNT is still real.
 */
export function parsePlayersJson(body: unknown): FivemPlayer[] | null {
  let j: unknown = body;
  if (typeof body === "string") {
    try {
      j = JSON.parse(body);
    } catch {
      return null;
    }
  }
  if (!Array.isArray(j)) return null;
  return j.slice(0, 4096).map((p) => {
    const o = (p && typeof p === "object" ? p : {}) as Record<string, unknown>;
    const id = Number(o.id);
    const ping = Number(o.ping);
    return {
      id: Number.isFinite(id) ? id : null,
      name: typeof o.name === "string" && o.name.length > 0 ? o.name.slice(0, 64) : null,
      ping: Number.isFinite(ping) ? ping : null,
    };
  });
}

/**
 * txAdmin's first-run PIN line. Verified against the bundled txAdmin core:
 * `console.warn("Use this PIN to add a new master account: " + chalkInversePad(pin))`
 * where pin = `(Math.random()*1e4).toFixed().padStart(4,"0")` — 4 digits (5 in
 * the rare round-up to 10000). ANSI colour codes are stripped first. Returns
 * the LAST PIN printed (a restart before setup prints a fresh one).
 */
export function parseTxAdminPin(log: string): string | null {
  // eslint-disable-next-line no-control-regex
  const clean = String(log ?? "").replace(/\x1b\[[0-9;]*m/g, "");
  let pin: string | null = null;
  for (const m of clean.matchAll(/Use this PIN to add a new master account:\s*(\d{4,5})\b/g)) pin = m[1];
  return pin;
}

/** The exact SSH tunnel command a customer runs to reach txAdmin. */
export function txAdminTunnelCommand(host: string, sshPort: number | null | undefined): string {
  const safeHost = /^[A-Za-z0-9.:-]{1,253}$/.test(host) ? host : "<server-ip>";
  const p = sshPort && sshPort !== 22 ? ` -p ${Math.trunc(sshPort)}` : "";
  return `ssh -N -L ${FIVEM_TXADMIN_PORT}:127.0.0.1:${FIVEM_TXADMIN_PORT}${p} root@${safeHost}`;
}

