/**
 * FiveM BYO licence key + per-server secrets — SERVER-ONLY (imports
 * lib/crypto-box, node:crypto). Never import from a client component.
 *
 * Model (docs/FIVEM-HOSTING-LEGAL-OPS.md, "BYO-key design"):
 *  - The customer brings their OWN Cfx.re server key (portal.cfx.re), bound by
 *    Cfx.re to their server's public IP. Nxeon never owns, pools, generates or
 *    shares keys — one key belongs to one customer's one server.
 *  - At rest it is AES-256-GCM sealed (lib/crypto-box `encryptSecret`, the same
 *    box BYOK/migration/company-mail secrets use) into the `_fivemLicenseEnc`
 *    marker of Server.gameConfig. The readable `sv_licenseKey` field is always
 *    stored BLANK, so no read path (settings form, admin JSON views, readiness
 *    checks, audit lines) ever carries the plaintext.
 *  - `_`-prefixed markers survive a Settings save (lib/actions-game-config.ts
 *    keeps them) and are never returned by validateConfig, so they never reach
 *    the browser.
 *  - The plaintext exists only (a) in the customer's own request, (b) in the
 *    worker's memory while it renders secrets.cfg, (c) in that 0600 file on
 *    the customer's own VM and in the cloud-init user-data of their VM (the
 *    same exposure as the VM's root password today).
 */
import { encryptSecret, decryptSecret } from "./crypto-box";
import { randomBytes } from "node:crypto";
import { isValidLicenseKey, parseResourceList, slotCapError, fivemSettingsFrom } from "./fivem";

export const FIVEM_LICENSE_MARKER = "_fivemLicenseEnc";
/** Encrypted JSON {rcon, playersToken} — minted once at provision, rotated on reinstall. */
export const FIVEM_SECRETS_MARKER = "_fivemSecretsEnc";

export type FivemPrepared =
  | { ok: true; values: Record<string, string | number | boolean>; keyChanged: boolean }
  | { ok: false; error: string };

/**
 * Validate the FiveM-specific rules validateConfig cannot express, and seal
 * the key. `values` are validateConfig's output; `previous` is the stored blob
 * (for the existing sealed key). `requireKey` is true at order time.
 * `seal=false` (live quote previews) validates without encrypting.
 */
export function prepareFivemConfig(args: {
  values: Record<string, string | number | boolean>;
  previous?: Record<string, unknown> | null;
  planSlots: number | null | undefined;
  requireKey: boolean;
  seal?: boolean;
}): FivemPrepared {
  const seal = args.seal !== false;
  const out: Record<string, string | number | boolean> = { ...args.values };
  const typed = String(out.sv_licenseKey ?? "").trim();
  const prevEnc = typeof args.previous?.[FIVEM_LICENSE_MARKER] === "string" ? (args.previous[FIVEM_LICENSE_MARKER] as string) : null;

  if (typed && !isValidLicenseKey(typed)) return { ok: false, error: "That doesn't look like a Cfx.re licence key (it starts with cfxk_)." };
  if (args.requireKey && !typed && !prevEnc) {
    return { ok: false, error: "Paste your own Cfx.re licence key (portal.cfx.re → Server registration keys). Every FiveM server needs one." };
  }

  const s = fivemSettingsFrom(out);
  const capErr = slotCapError(s.sv_maxclients, args.planSlots, s.licenceTier, s.onesync);
  if (capErr) return { ok: false, error: capErr };
  const res = parseResourceList(s.resources);
  if (!res.ok) return { ok: false, error: res.error };

  out.sv_licenseKey = "";
  if (typed && seal) out[FIVEM_LICENSE_MARKER] = encryptSecret(typed);
  else if (typed && !seal) out.sv_licenseKey = typed; // preview only — never persisted
  return { ok: true, values: out, keyChanged: !!typed };
}

/** The customer's licence key in plaintext, for the worker only. */
export function fivemLicenseKey(gameConfig: unknown): string | null {
  const g = (gameConfig ?? {}) as Record<string, unknown>;
  const enc = typeof g[FIVEM_LICENSE_MARKER] === "string" ? (g[FIVEM_LICENSE_MARKER] as string) : null;
  const plain = decryptSecret(enc);
  return plain && isValidLicenseKey(plain) ? plain : null;
}

function token(n: number): string {
  return randomBytes(n * 2).toString("base64").replace(/[^A-Za-z0-9]/g, "").slice(0, n);
}

export type FivemSecrets = { rconPassword: string; playersToken: string };

export function mintFivemSecrets(): FivemSecrets {
  return { rconPassword: token(24), playersToken: token(32) };
}

export function sealFivemSecrets(s: FivemSecrets): string {
  return encryptSecret(JSON.stringify(s));
}

export function fivemSecrets(gameConfig: unknown): FivemSecrets | null {
  const g = (gameConfig ?? {}) as Record<string, unknown>;
  const plain = decryptSecret(typeof g[FIVEM_SECRETS_MARKER] === "string" ? (g[FIVEM_SECRETS_MARKER] as string) : null);
  if (!plain) return null;
  try {
    const j = JSON.parse(plain) as Partial<FivemSecrets>;
    if (typeof j.rconPassword === "string" && typeof j.playersToken === "string") return { rconPassword: j.rconPassword, playersToken: j.playersToken };
  } catch {
    /* fall through */
  }
  return null;
}

