  const capErr = slotCapError(s.sv_maxclients, args.planSlots, s.licenceTier, s.onesync);
  if (capErr) return { ok: false, error: capErr };
  const res = parseResourceList(s.resources);
  if (!res.ok) return { ok: false, error: res.error };

  out.sv_licenseKey = "";
  if (typed && seal) out[FIVEM_LICENSE_MARKER] = encryptSecret(typed);
  else if (typed && !seal) out.sv_licenseKey = typed; // preview only — never persisted
  return { ok: true, values: out, keyChanged: !!typed };
}

/** The customer's licence key in plaintext, for the worker only. */
export function fivemLicenseKey(gameConfig: unknown): string | null {
  const g = (gameConfig ?? {}) as Record<string, unknown>;
  const enc = typeof g[FIVEM_LICENSE_MARKER] === "string" ? (g[FIVEM_LICENSE_MARKER] as string) : null;
  const plain = decryptSecret(enc);
  return plain && isValidLicenseKey(plain) ? plain : null;
}

function token(n: number): string {
  return randomBytes(n * 2).toString("base64").replace(/[^A-Za-z0-9]/g, "").slice(0, n);
}

export type FivemSecrets = { rconPassword: string; playersToken: string };

export function mintFivemSecrets(): FivemSecrets {
  return { rconPassword: token(24), playersToken: token(32) };
}

export function sealFivemSecrets(s: FivemSecrets): string {
  return encryptSecret(JSON.stringify(s));
}

export function fivemSecrets(gameConfig: unknown): FivemSecrets | null {
  const g = (gameConfig ?? {}) as Record<string, unknown>;
  const plain = decryptSecret(typeof g[FIVEM_SECRETS_MARKER] === "string" ? (g[FIVEM_SECRETS_MARKER] as string) : null);
  if (!plain) return null;
  try {
    const j = JSON.parse(plain) as Partial<FivemSecrets>;
    if (typeof j.rconPassword === "string" && typeof j.playersToken === "string") return { rconPassword: j.rconPassword, playersToken: j.playersToken };
  } catch {
    /* fall through */
  }
  return null;
}

