mode="\${1:-install}"
NX_FIVEM_CHANNEL=recommended; NX_FIVEM_BUILD=""; NX_FIVEM_URL=""; NX_FIVEM_SHA256=""; NX_FIVEM_KNOWN=""
[ -f "$R/nx/artifact.env" ] && . "$R/nx/artifact.env"
case "$NX_FIVEM_CHANNEL" in recommended|latest) ;; *) say "ERR:bad channel"; exit 2 ;; esac
url_re='^https://runtime\\.fivem\\.net/artifacts/fivem/build_proot_linux/master/([0-9]{3,6})-[0-9a-f]{40}/fx\\.tar\\.xz$'

stage() {
  if [ -n "$NX_FIVEM_BUILD" ]; then
    build="$NX_FIVEM_BUILD"; url="$NX_FIVEM_URL"; want="$NX_FIVEM_SHA256"
  else
    json=$(curl -fsS --proto =https --max-time 30 '${FIVEM_CHANGELOG_URL}') || { say "ERR:changelog unreachable"; return 3; }
    line=$(printf '%s' "$json" | python3 -c 'import sys,json; j=json.load(sys.stdin); c=sys.argv[1]; print(j.get(c,""), j.get(c+"_download",""))' "$NX_FIVEM_CHANNEL" 2>/dev/null) || { say "ERR:changelog unparseable"; return 3; }
    build=\${line%% *}; url=\${line#* }; want=""
    for kv in $(printf '%s' "$NX_FIVEM_KNOWN" | tr ',' ' '); do [ "\${kv%%:*}" = "$build" ] && want="\${kv#*:}"; done
  fi
  if ! [[ "$url" =~ $url_re ]] || [ "\${BASH_REMATCH[1]}" != "$build" ]; then say "ERR:artifact url not allowlisted"; return 4; fi
  cur=$(cat "$R/artifact/.nx-build" 2>/dev/null || true)
  if [ "$cur" = "$build" ] && [ -x "$R/artifact/run.sh" ]; then say "CURRENT:$build"; return 0; fi
  tmp=$(mktemp -d "$R/.dl.XXXXXX") || return 5
  trap 'rm -rf "$tmp"' RETURN
  len=$(curl -fsSI --proto =https --max-time 30 "$url" | tr -d '\\r' | awk 'tolower($1)=="content-length:"{print $2}' | tail -1)
  curl -fsS --proto =https --max-time 900 --retry 3 -o "$tmp/fx.tar.xz" "$url" || { say "ERR:download failed"; return 5; }
  got=$(stat -c %s "$tmp/fx.tar.xz")
  if [ -z "$len" ] || [ "$got" != "$len" ]; then say "ERR:size mismatch ($got vs \${len:-?})"; return 6; fi
  xz -t "$tmp/fx.tar.xz" 2>/dev/null || { say "ERR:xz integrity check failed"; return 6; }
  sha=$(sha256sum "$tmp/fx.tar.xz" | awk '{print $1}')
  if [ -n "$want" ] && [ "$sha" != "$want" ]; then say "ERR:sha256 mismatch for build $build"; return 6; fi
  tar -tJf "$tmp/fx.tar.xz" > "$tmp/list" || { say "ERR:tar list failed"; return 6; }
  if grep -qvE '^(run\\.sh|alpine(/.*)?)$' "$tmp/list" || grep -qE '(^/|(^|/)\\.\\.(/|$))' "$tmp/list"; then say "ERR:unexpected archive members"; return 6; fi
  grep -qx 'run.sh' "$tmp/list" && grep -qx 'alpine/opt/cfx-server/FXServer' "$tmp/list" || { say "ERR:archive missing run.sh/FXServer"; return 6; }
  rm -rf "$R/artifact.new"; mkdir -p "$R/artifact.new"
  tar -xJf "$tmp/fx.tar.xz" -C "$R/artifact.new" --no-same-owner || { say "ERR:extract failed"; return 6; }
  echo "$build" > "$R/artifact.new/.nx-build"; echo "$sha" > "$R/artifact.new/.nx-sha256"
  chmod -R a+rX,go-w "$R/artifact.new"
  say "SHA256:$sha"; say "STAGED:$build"
}

swap() {
  [ -d "$R/artifact.new" ] || { say "ERR:nothing staged"; return 7; }
  rm -rf "$R/artifact.prev"
  [ -d "$R/artifact" ] && mv "$R/artifact" "$R/artifact.prev"
  mkdir -p "$R/artifact" && rmdir "$R/artifact" && mv "$R/artifact.new" "$R/artifact" || { say "ERR:swap failed"; [ -d "$R/artifact.prev" ] && mv "$R/artifact.prev" "$R/artifact"; return 7; }
  say "SWAPPED:$(cat "$R/artifact/.nx-build")"
}

case "$mode" in
  fetch) stage ;;
  swap) swap ;;
  install) out=$(stage); rc=$?; printf '%s\\n' "$out"; [ $rc -eq 0 ] || exit $rc; printf '%s' "$out" | grep -q '^NXFA:STAGED' && { swap || exit $?; }; exit 0 ;;
  *) say "ERR:usage"; exit 2 ;;
esac
`;

/** Default Cfx.re resources, only when the customer has none yet (never overwrites their resources/). */
export const NX_RESOURCES_SH = `#!/bin/bash
set -u
R=${FIVEM_ROOT}/server-data/resources
mkdir -p "$R"
if [ -z "$(ls -A "$R" 2>/dev/null)" ]; then
  tmp=$(mktemp -d)
  if curl -fsSL --proto =https --max-time 120 '${CFX_SERVER_DATA_TARBALL}' -o "$tmp/sd.tgz" && tar -xzf "$tmp/sd.tgz" -C "$tmp" --no-same-owner; then
    cp -a "$tmp"/cfx-server-data-*/resources/. "$R"/ && echo "NXFR:OK"
  else
    echo "NXFR:FAIL"
  fi
  rm -rf "$tmp"
fi
`;

/**
 * The static OsTemplate.setupScript (stored in the DB by prisma/seed-fivem.ts).
 * `curl -fsSL https://get.docker.com | sh &&` is the exact prefix
 * `skipDockerInstallIfPresent` recognises.
 */
export function fivemSetupScript(): string {
  return [
    `curl -fsSL https://get.docker.com | sh && command -v xz >/dev/null 2>&1 || { apt-get install -y xz-utils || true; }`,
    `getent group fivem >/dev/null 2>&1 || groupadd -r -g ${FIVEM_UID} fivem; id -u fivem >/dev/null 2>&1 || useradd -r -u ${FIVEM_UID} -g ${FIVEM_UID} -M -d ${FIVEM_ROOT} -s /usr/sbin/nologin fivem`,
    `mkdir -p ${FIVEM_ROOT}/artifact ${FIVEM_ROOT}/server-data/resources ${FIVEM_ROOT}/txData ${FIVEM_ROOT}/nx`,
    FIVEM_FILES_PLACEHOLDER,
    `bash ${FIVEM_ROOT}/nx/nx-artifact.sh install`,
    `bash ${FIVEM_ROOT}/nx/nx-resources.sh`,
    `chown -R ${FIVEM_UID}:${FIVEM_UID} ${FIVEM_ROOT}/server-data ${FIVEM_ROOT}/txData && chmod 0600 ${FIVEM_ROOT}/server-data/secrets.cfg && chmod 0700 ${FIVEM_ROOT}/nx && chown -R root:${FIVEM_UID} ${FIVEM_ROOT}/nx && chmod 0750 ${FIVEM_ROOT}/nx && chmod 0640 ${FIVEM_ROOT}/nx/runtime.env ${FIVEM_ROOT}/nx/artifact.env && chmod 0755 ${FIVEM_ROOT}/nx/nx-start.sh`,
    [
      `docker run -d --name fivem --restart unless-stopped --user ${FIVEM_UID}:${FIVEM_UID}`,
      `-p ${FIVEM_GAME_PORT}:${FIVEM_GAME_PORT}/tcp -p ${FIVEM_GAME_PORT}:${FIVEM_GAME_PORT}/udp -p 127.0.0.1:${FIVEM_TXADMIN_PORT}:${FIVEM_TXADMIN_PORT}/tcp`,
      `-e TXHOST_DATA_PATH=${FIVEM_ROOT}/txData -e TXHOST_TXA_PORT=${FIVEM_TXADMIN_PORT} -e TXHOST_FXS_PORT=${FIVEM_GAME_PORT}`,
      `-e TXHOST_GAME_NAME=fivem -e TXHOST_PROVIDER_NAME=Nxeon -e TXHOST_IGNORE_DEPRECATED_CONFIGS=true`,
      `-v ${FIVEM_ROOT}/artifact:${FIVEM_ROOT}/artifact:ro -v ${FIVEM_ROOT}/server-data:${FIVEM_ROOT}/server-data`,
      `-v ${FIVEM_ROOT}/txData:${FIVEM_ROOT}/txData -v ${FIVEM_ROOT}/nx:${FIVEM_ROOT}/nx:ro`,
      `-w ${FIVEM_ROOT}/server-data ${FIVEM_IMAGE} bash ${FIVEM_ROOT}/nx/nx-start.sh`,
    ].join(" "),
  ].join("\n");
}

/** `printf %s <b64> | base64 -d > path` — content never passes through shell parsing. */
function writeFileCmd(path: string, content: string, mode: string): string {
  if (!/^\/opt\/fivem\/[A-Za-z0-9._/-]+$/.test(path) || path.includes("..")) throw new Error(`unsafe fivem path ${path}`);
  if (!/^0[0-7]{3}$/.test(mode)) throw new Error("bad mode");
  const b64 = Buffer.from(content, "utf8").toString("base64");
  return `printf '%s' '${b64}' | base64 -d > ${path} && chmod ${mode} ${path}`;
}

export type FivemRenderInput = {
  gameConfig: Record<string, unknown> | null | undefined;
  planSlots: number | null | undefined;
  licenseKey: string | null;
  rconPassword: string;
  playersToken: string;
};

/** Every generated file, path → [content, mode]. Shared by provision and applyFivem. */
export function fivemFiles(input: FivemRenderInput): Record<string, [string, string]> {
  const s = fivemSettingsFrom(input.gameConfig ?? {});
  return {
    [`${FIVEM_ROOT}/nx/nx-start.sh`]: [NX_START_SH, "0755"],
    [`${FIVEM_ROOT}/nx/nx-artifact.sh`]: [NX_ARTIFACT_SH, "0700"],
    [`${FIVEM_ROOT}/nx/nx-resources.sh`]: [NX_RESOURCES_SH, "0700"],
    [`${FIVEM_ROOT}/nx/runtime.env`]: [renderRuntimeEnv(s, { planSlots: input.planSlots }), "0644"],
    [`${FIVEM_ROOT}/nx/artifact.env`]: [renderArtifactEnv(s), "0644"],
    [`${FIVEM_ROOT}/server-data/server.cfg`]: [renderServerCfg(s, { planSlots: input.planSlots }), "0644"],
    [`${FIVEM_ROOT}/server-data/secrets.cfg`]: [
      renderSecretsCfg({ licenseKey: input.licenseKey, rconPassword: input.rconPassword, playersToken: input.playersToken }),
      "0600",
    ],
  };
}

/**
 * Provision-time substitution: replace the placeholder with commands that
 * write every generated file. No-op for any other family or a script without
 * the placeholder (so a hand-edited OsTemplate can never get files injected
 * somewhere unexpected).
 */
export function applyFivemSetup(setupScript: string, family: string | null, input: FivemRenderInput): string {
  if (family !== "fivem" || !setupScript.includes(FIVEM_FILES_PLACEHOLDER)) return setupScript;
  const cmds = Object.entries(fivemFiles(input)).map(([p, [c, m]]) => writeFileCmd(p, c, m));
  return setupScript.replace(FIVEM_FILES_PLACEHOLDER, cmds.join("\n"));
}

/** The same file set as one remote shell script (worker applyFivem over SSH). */
export function fivemApplyScript(input: FivemRenderInput, opts: { includeScripts?: boolean } = {}): string {
  const files = fivemFiles(input);
  const keep = Object.entries(files).filter(([p]) => opts.includeScripts || !/\/nx\/nx-[a-z]+\.sh$/.test(p));
  return [
    "set -e",
    `[ -d ${FIVEM_ROOT}/server-data ] || { echo NXFC:NOROOT; exit 3; }`,
    ...keep.map(([p, [c, m]]) => writeFileCmd(p, c, m)),
    `chown ${FIVEM_UID}:${FIVEM_UID} ${FIVEM_ROOT}/server-data/server.cfg ${FIVEM_ROOT}/server-data/secrets.cfg`,
    "echo NXFC:OK",
  ].join("\n");
}

