/**
 * FiveM worker helpers (feature-flagged family — see lib/fivem.ts). Everything
 * here runs against the CUSTOMER'S OWN game VM over the platform's existing SSH
 * connection and only ever interpolates compile-time constants or values that
 * passed a strict allowlist (alphanumeric tokens, integers) into a command.
 *
 *  - applyFivem         Settings save → rewrite server.cfg / secrets.cfg /
 *                       runtime.env / artifact.env (worker/game-config.ts
 *                       applyRealConfig "fivem" case).
 *  - readFivemPlayers   /players.json on the guest's loopback WITH the
 *                       per-server players token (anonymous callers get no
 *                       names on current FXServer builds) — feeds
 *                       playerTrackingSweep.
 *  - readTxAdminAccess  txAdmin first-run PIN from the unit's journal, or
 *                       "already set up" when txData has an admins.json.
 *  - probeFivemPublic   GET http://<public-ip>:30120/info.json from the
 *                       PRIMARY (outside the guest and its node) — the
 *                       FXServer-specific readiness proof.
 */
import type { Client } from "ssh2";
import { db } from "../lib/db";
import { exec, QUICK_TIMEOUT_MS } from "../lib/ssh-exec";
import { FIVEM_GAME_PORT, parseInfoJson, parsePlayersJson, parseTxAdminPin, type FivemInfo, type FivemPlayer } from "../lib/fivem";
import { fivemApplyScript, FIVEM_ROOT } from "../lib/fivem-install";
import { deriveFivemSecrets, fivemLicenseKey } from "../lib/fivem-license";

type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };

export async function applyFivem(conn: Client, serverId: string, values: Record<string, string | number | boolean>): Promise<ApplyOutcome> {
  // The validated `values` carry no markers (validateConfig drops `_` keys), so
  // the sealed licence key and the plan's slot count are read fresh here.
  const row = await db.server.findUnique({
    where: { id: serverId },
    select: { gameConfig: true, gamePlan: { select: { slots: true } } },
  });
  if (!row) return { ok: false, applied: [], notes: ["Server not found."] };
  const stored = (row.gameConfig as Record<string, unknown> | null) ?? {};
  const script = fivemApplyScript({
    gameConfig: { ...stored, ...values },
    planSlots: row.gamePlan?.slots ?? null,
    licenseKey: fivemLicenseKey(stored),
    ...deriveFivemSecrets(serverId),
  });
  const r = await exec(conn, script, QUICK_TIMEOUT_MS);
  if (/NXFC:NOROOT/.test(r.stdout)) {
    return { ok: false, applied: [], notes: [`${FIVEM_ROOT}/server-data is missing on the server — reinstall the game from the Danger Zone.`] };
  }
  if (!/NXFC:OK/.test(r.stdout)) {
    return { ok: false, applied: [], notes: [`Writing server.cfg failed (exit ${r.code ?? "?"}).`] };
  }
  return {
    ok: true,
    applied: Object.keys(values).filter((k) => k !== "sv_licenseKey"),
    notes: [
      "server.cfg, secrets.cfg and the runtime settings were rewritten. Changes take effect on the next restart.",
      ...(fivemLicenseKey(stored) ? [] : ["No Cfx.re licence key is saved — the server will not start until you add one."]),
    ],
  };
}

export async function readFivemPlayers(conn: Client, serverId: string): Promise<FivemPlayer[] | null> {
  const { playersToken } = deriveFivemSecrets(serverId);
  if (!/^[A-Za-z0-9]{16,64}$/.test(playersToken)) return null;
  const r = await exec(
    conn,
    `curl -fsS --max-time 5 -H 'X-Players-Token: ${playersToken}' http://127.0.0.1:${FIVEM_GAME_PORT}/players.json`,
    QUICK_TIMEOUT_MS
  );
  if (r.code !== 0) return null;
  return parsePlayersJson(r.stdout);
}

export type TxAdminAccess = { state: "pin"; pin: string } | { state: "configured" } | { state: "disabled" } | { state: "unknown"; detail: string };

export async function readTxAdminAccess(conn: Client): Promise<TxAdminAccess> {
  const r = await exec(
    conn,
    [
      `grep -q '^NX_TXADMIN=1' ${FIVEM_ROOT}/nx/runtime.env 2>/dev/null || { echo NXTX:DISABLED; exit 0; }`,
      `ls ${FIVEM_ROOT}/txData/admins.json >/dev/null 2>&1 && { echo NXTX:CONFIGURED; exit 0; }`,
      `journalctl -u fivem --no-pager -o cat -n 3000 2>/dev/null | grep -a 'Use this PIN to add a new master account' | tail -1`,
    ].join("\n"),
    QUICK_TIMEOUT_MS
  );
  if (/NXTX:DISABLED/.test(r.stdout)) return { state: "disabled" };
  if (/NXTX:CONFIGURED/.test(r.stdout)) return { state: "configured" };
  const pin = parseTxAdminPin(r.stdout);
  return pin ? { state: "pin", pin } : { state: "unknown", detail: "txAdmin has not printed a PIN yet — is the server running?" };
}

/**
 * The outside-in readiness proof: an HTTP GET of FXServer's own /info.json at
 * the server's PUBLIC address, from the primary. `host` must be the public IP
 * (dedicated IPv4 — fivem orders always have one, see lib/game-order.ts).
 */
export async function probeFivemPublic(host: string, port = FIVEM_GAME_PORT, timeoutMs = 6000): Promise<{ ok: boolean; info: FivemInfo | null; error?: string }> {
  if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return { ok: false, info: null, error: "not an IPv4 address" };
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    const res = await fetch(`http://${host}:${port}/info.json`, { signal: ctl.signal, redirect: "error" });
    if (!res.ok) return { ok: false, info: null, error: `HTTP ${res.status}` };
    const info = parseInfoJson(await res.text());
    return info ? { ok: true, info } : { ok: false, info: null, error: "answer is not FXServer's /info.json" };
  } catch (e) {
    return { ok: false, info: null, error: String((e as Error)?.message ?? e).slice(0, 160) };
  } finally {
    clearTimeout(t);
  }
}

