   *  full-price order or a coupon that doesn't need one-per-person
   *  enforcement on the card leg. */
  couponReservationToken?: string | null,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  if (sold.chargeCents < amountCents) {
    throw new Error(`Game order payment session: card leg ${amountCents}c exceeds the order total ${sold.chargeCents}c`);
  }
  const slim = {
    gamePlanId: intent.gamePlanId,
    termMonths: intent.termMonths,
    serverName: intent.serverName,
    hostname: intent.hostname,
    variant: intent.variant,
    subdomain: intent.subdomain,
    dedicatedIp: intent.dedicatedIp,
    // REGION (2026-10-01): this slim intent used to omit it, so every card-paid
    // game order reached placeGameOrder with no region and was placed by the
    // global-capacity scheduler (Malaysia/Germany customers landed in Canada).
    region: intent.region,
    provider: intent.provider,
    regionSource: intent.regionSource,
  };
  const configJson = intent.config ? JSON.stringify(intent.config) : "";
  const carryConfig = configJson !== "" && configJson.length <= 480;
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      // Custom Checkout's client-side `checkout.confirm({ savePaymentMethod })`
      // (components/customer/PaymentStep.tsx) throws `IntegrationError:
      // savePaymentMethod cannot be used unless the Checkout Session was created
      // with saved_payment_method_options[payment_method_save]=enabled` without
      // this — a real bug caught by an end-to-end staging payment attempt before
      // promoting to prod: every card payment through the embedded PaymentStep
      // failed 100% of the time with a generic "something went wrong" message.
      saved_payment_method_options: { payment_method_save: "enabled" },
