/**
 * FiveM (Cfx.re FXServer) — OsTemplate + GamePlan seed. FEATURE-FLAGGED.
 *
 * DO NOT RUN until the owner has (1) cleared the legal blocker in
 * docs/FIVEM-HOSTING-LEGAL-OPS.md (Creator PLA s5.2 "Authorized Service" /
 * "Unauthorized Service Provider" — Nxeon is not a listed hosting partner),
 * (2) approved the prices below, and (3) live-verified one provision on a
 * non-primary test node. It refuses to run unless FIVEM_ENABLED=1 AND
 * FIVEM_SEED_CONFIRM=yes are both set, so nothing reaches any database by
 * accident.
 *
 * PRICES ARE PROPOSALS, NOT DECISIONS. Public competitor pages read
 * 2026-10-01 (see the legal/ops doc, "Pricing evidence"):
 *   - Shockbyte (authorized partner): 12 players / 3 GB $12.99/mo,
 *     24 players / 4 GB $15.99/mo, unlimited players / 6 GB $24.99/mo
 *   - GPORTAL (authorized partner): 10 slots $9.00 / 30 days, 48 slots $36.95 / 30 days
 *   - ZAP-Hosting (authorized partner): "from $8.93/Month"
 * Our tiers are sized for real FXServer use (a framework server — QBCore/ESX
 * plus MySQL — routinely needs 4 GB+ before players), and every FiveM order
 * ALSO requires a dedicated IPv4 (lib/game-order.ts), billed on top at the
 * admin-set dedicated-IP rate — so the customer's real monthly cost is
 * tier + IP. Slot counts are the tier's sizing target; the server's real cap
 * is min(tier slots, the customer's own Cfx.re licence tier) — see
 * lib/fivem.ts effectiveSlotCap.
 *
 * Run (staging first, only after the above):
 *   cd /opt/nxeon-staging && FIVEM_ENABLED=1 FIVEM_SEED_CONFIRM=yes npx tsx prisma/seed-fivem.ts
 * Idempotent (upserts by slug / gameFamily+name).
 */
import { PrismaClient } from "@prisma/client";
import { fivemSetupScript } from "../lib/fivem-install";

type TierSpec = { name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };

/** PROPOSED tiers — owner to confirm/replace the prices before seeding. */
export const FIVEM_PROPOSED_TIERS: TierSpec[] = [
  { name: "FiveM — 4 GB / 48 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 48, priceCents: 1499 },
  { name: "FiveM — 8 GB / 128 players", ramMB: 8192, cpuCores: 4, diskGB: 50, slots: 128, priceCents: 2799, featured: true },
  { name: "FiveM — 16 GB / 255 players", ramMB: 16384, cpuCores: 6, diskGB: 80, slots: 255, priceCents: 4999 },
];

async function main() {
  if (process.env.FIVEM_ENABLED !== "1" || process.env.FIVEM_SEED_CONFIRM !== "yes") {
    console.error(
      "Refusing to seed FiveM: set FIVEM_ENABLED=1 and FIVEM_SEED_CONFIRM=yes, and only after the legal, pricing and live-verification steps in docs/FIVEM-HOSTING-LEGAL-OPS.md."
    );
    process.exit(2);
  }
  const db = new PrismaClient();
  try {
    const os = await db.osTemplate.upsert({
      where: { slug: "fivem" },
      create: {
        slug: "fivem", name: "FiveM Server", category: "APPLICATION", family: "fivem", version: "", logo: "fivem",
        vmid: 9000, baseVmid: 9000, setupScript: fivemSetupScript(), minRamMB: 4096, minDiskGB: 30,
        licenseRequired: false, featured: false, sortOrder: 150, active: true,
      },
      update: { name: "FiveM Server", setupScript: fivemSetupScript(), minRamMB: 4096, minDiskGB: 30, active: true },
    });
    console.log(`  osTemplate fivem → ${os.id}`);

    const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
    if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
    const largest = plans[plans.length - 1];
    let sortOrder = 0;
    for (const t of FIVEM_PROPOSED_TIERS) {
      const basePlan = plans.find((p) => p.ramMB >= t.ramMB) ?? largest;
      const data = {
        gameFamily: "fivem", name: t.name, ramMB: t.ramMB, cpuCores: t.cpuCores, diskGB: t.diskGB, slots: t.slots,
        priceCents: t.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: os.id,
        featured: t.featured ?? false, active: true, sortOrder: sortOrder++,
      };
      const existing = await db.gamePlan.findFirst({ where: { gameFamily: "fivem", name: t.name } });
      if (existing) await db.gamePlan.update({ where: { id: existing.id }, data });
      else await db.gamePlan.create({ data });
      console.log(`  plan ${t.name.padEnd(32)} base=${basePlan.name}`);
    }
  } finally {
    await db.$disconnect();
  }
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

