import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, chmodSync, readFileSync, existsSync, mkdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

process.env.AUTH_SECRET ||= "test-auth-secret-for-fivem-unit-tests";

import {
  fivemEnabled,
  isValidLicenseKey,
  maskLicenseKey,
  licenceSlotCap,
  effectiveSlotCap,
  slotCapError,
  parseChangelog,
  renderServerCfg,
  renderSecretsCfg,
  renderRuntimeEnv,
  renderArtifactEnv,
  fivemSettingsFrom,
  parseResourceList,
  parseInfoJson,
  parsePlayersJson,
  parseTxAdminPin,
  txAdminTunnelCommand,
  cfgQuote,
  FIVEM_KNOWN_ARTIFACTS,
} from "../lib/fivem.ts";
import { prepareFivemConfig, fivemLicenseKey, sealFivemIntentConfig, deriveFivemSecrets, FIVEM_LICENSE_MARKER } from "../lib/fivem-license.ts";
import { fivemSetupScript, applyFivemSetup, fivemApplyScript, NX_ARTIFACT_SH, NX_START_SH, NX_RESOURCES_SH, FIVEM_FILES_PLACEHOLDER } from "../lib/fivem-install.ts";
import { validateConfig, schemaFor } from "../lib/game-config.ts";
import { buildGameSetupScript, dockerHostMountsFrom, dockerContainerNameFrom, skipDockerInstallIfPresent } from "../worker/game-variant.ts";
import { updateCommand, updatesFromSteam } from "../lib/game-update-verify.ts";
import { GAME_PORT, joinPortsFor } from "../lib/games.ts";
import { controlSpec } from "../lib/game-control.ts";

const KEY = "cfxk_AbCdEfGhIjKlMnOpQrStU_vWxYz1";

function bashSyntaxOk(script: string): { ok: boolean; err: string } {
  const r = spawnSync("bash", ["-n"], { input: script, encoding: "utf8" });
  return { ok: r.status === 0, err: r.stderr };
}

// --------------------------------------------------------------------------- flag

test("FIVEM_ENABLED: off unless exactly '1'", () => {
  assert.equal(fivemEnabled({}), false);
  assert.equal(fivemEnabled({ FIVEM_ENABLED: "true" }), false);
  assert.equal(fivemEnabled({ FIVEM_ENABLED: "0" }), false);
  assert.equal(fivemEnabled({ FIVEM_ENABLED: "1" }), true);
});

// --------------------------------------------------------------------------- key

test("licence key: cfxk_ format accepted, junk and injection rejected, masked for display", () => {
  assert.ok(isValidLicenseKey(KEY));
  for (const bad of ["", "abc", "cfxk_short", "CFXK_AbCdEfGhIjKlMnOpQrStU", `cfxk_AbCdEfGhIjKlMnOpQrStU" ; quit`, "cfxk_AbCdEfGhIjKlMnOpQrStU'$(id)'", "x".repeat(300)]) {
    assert.equal(isValidLicenseKey(bad), false, bad);
  }
  assert.equal(maskLicenseKey(KEY), "cfxk_…xYz1");
  assert.ok(!maskLicenseKey(KEY).includes("AbCd"));
});

// --------------------------------------------------------------------------- caps

test("slot caps follow fivem.net/server-hosting tiers and the plan", () => {
  assert.equal(licenceSlotCap("default", "on"), 48);
  assert.equal(licenceSlotCap("argentum", "on"), 64);
  assert.equal(licenceSlotCap("aurum", "on"), 128);
  assert.equal(licenceSlotCap("aurum", "legacy"), 64);
  assert.equal(licenceSlotCap("platinum", "on"), 2048);
  assert.equal(licenceSlotCap("platinum", "legacy"), 128);
  assert.equal(licenceSlotCap("platinum", "off"), 32);
  assert.equal(effectiveSlotCap(255, "platinum", "on"), 255); // plan binds
  assert.equal(effectiveSlotCap(255, "default", "on"), 48); // licence binds
  assert.equal(effectiveSlotCap(null, "aurum", "on"), 128);
  assert.equal(slotCapError(48, 48, "default", "on"), null);
  assert.match(slotCapError(64, 255, "default", "on") ?? "", /Cfx\.re licence tier/);
  assert.match(slotCapError(200, 128, "platinum", "on") ?? "", /limited to 128 on this plan/);
});

// --------------------------------------------------------------------------- artifacts

// Captured verbatim (trimmed support_policy) from a live GET of the official
// endpoint on 2026-10-01.
const CHANGELOG = {
  critical: "7290", recommended: "35245", optional: "7290", latest: "36897",
  critical_download: "https://runtime.fivem.net/artifacts/fivem/build_proot_linux/master/7290-a654bcc2adfa27c4e020fc915a1a6343c3b4f921/fx.tar.xz",
  critical_txadmin: "7.0.0",
  recommended_download: "https://runtime.fivem.net/artifacts/fivem/build_proot_linux/master/35245-6efb47dff473c0e2a12fb50b08d74c0eb24a50d5/fx.tar.xz",
  recommended_txadmin: "8.1.1",
  latest_download: "https://runtime.fivem.net/artifacts/fivem/build_proot_linux/master/36897-e34d12cd9a39cc223548a5be1ab09f60e9183051/fx.tar.xz",
  latest_txadmin: "8.1.1",
  support_policy: { "36897": "9999-12-31T23:59:59.9999999", "35245": "9999-12-31T23:59:59.9999999" },
};

test("changelog parse: real JSON resolves both channels; tampered URLs are refused", () => {
  assert.deepEqual(parseChangelog(CHANGELOG, "recommended"), { build: "35245", url: CHANGELOG.recommended_download, txadmin: "8.1.1" });
  assert.equal(parseChangelog(CHANGELOG, "latest")?.build, "36897");
  assert.equal(parseChangelog({ ...CHANGELOG, recommended_download: "https://evil.example/35245-6efb47dff473c0e2a12fb50b08d74c0eb24a50d5/fx.tar.xz" }, "recommended"), null);
  assert.equal(parseChangelog({ ...CHANGELOG, recommended_download: "http://runtime.fivem.net/artifacts/fivem/build_proot_linux/master/35245-6efb47dff473c0e2a12fb50b08d74c0eb24a50d5/fx.tar.xz" }, "recommended"), null);
  assert.equal(parseChangelog({ ...CHANGELOG, recommended: "36897" }, "recommended"), null, "build number must match the URL");
  assert.equal(parseChangelog(null, "recommended"), null);
  assert.ok(FIVEM_KNOWN_ARTIFACTS["35245"].url === CHANGELOG.recommended_download);
});

// --------------------------------------------------------------------------- cfg

test("server.cfg: endpoints, defaults + extras, caps applied, secrets NOT in it", () => {
  const s = fivemSettingsFrom({ sv_hostname: "My RP", sv_maxclients: 500, licenceTier: "aurum", onesync: "on", resources: "qb-core, ox_lib", tags: "rp, serious", gameBuild: "3095", sv_password: "letmein" });
  const cfg = renderServerCfg(s, { planSlots: 128 });
  assert.match(cfg, /^endpoint_add_tcp "0\.0\.0\.0:30120"$/m);
  assert.match(cfg, /^endpoint_add_udp "0\.0\.0\.0:30120"$/m);
  assert.match(cfg, /^sv_maxclients 128$/m, "500 requested, plan 128 / aurum 128 → 128");
  assert.match(cfg, /^ensure chat$/m);
  assert.match(cfg, /^ensure qb-core$/m);
  assert.match(cfg, /^ensure ox_lib$/m);
  assert.match(cfg, /^set onesync on$/m);
  assert.match(cfg, /^sv_enforceGameBuild 3095$/m);
  assert.match(cfg, /^sets tags "rp, serious"$/m);
  assert.match(cfg, /^sv_password "letmein"$/m);
  assert.match(cfg, /^exec secrets\.cfg$/m);
  assert.doesNotMatch(cfg, /sv_licenseKey|rcon_password|sv_playersToken/);
});

test("server.cfg: a hostname cannot end the command or the quote", () => {
  const s = fivemSettingsFrom({ sv_hostname: 'x" ; sv_licenseKey "stolen' });
  const cfg = renderServerCfg(s);
  const line = cfg.split("\n").find((l) => l.startsWith("sv_hostname"))!;
  assert.equal(line, 'sv_hostname "x  sv_licenseKey stolen"');
  assert.equal(cfgQuote("a\nb;c\"d"), '"abcd"');
});

test("resource list: valid names only", () => {
  assert.deepEqual(parseResourceList("a, b c,,a"), { ok: true, names: ["a", "b", "c"] });
  assert.equal(parseResourceList("good, ../evil").ok, false);
  assert.equal(parseResourceList("x;quit").ok, false);
});

test("secrets.cfg only carries allowlisted values", () => {
  const out = renderSecretsCfg({ licenseKey: KEY, rconPassword: "abcDEF123456xyz", playersToken: "a".repeat(32) });
  assert.match(out, new RegExp(`^sv_licenseKey "${KEY}"$`, "m"));
  assert.match(out, /^rcon_password "abcDEF123456xyz"$/m);
  assert.match(out, /^set sv_playersToken "a{32}"$/m);
  const bad = renderSecretsCfg({ licenseKey: 'cfxk_x" ; quit', rconPassword: "short", playersToken: "has space in it at all" });
  assert.doesNotMatch(bad, /sv_licenseKey|rcon_password|sv_playersToken/);
});

test("runtime.env / artifact.env are integers and fixed tokens only", () => {
  const s = fivemSettingsFrom({ txadmin: true, licenceTier: "platinum", onesync: "on", artifactChannel: "latest" });
  assert.equal(renderRuntimeEnv(s, { planSlots: 255 }), "NX_TXADMIN=1\nTXHOST_MAX_SLOTS=255\n");
  const a = renderArtifactEnv(s);
  assert.match(a, /^NX_FIVEM_CHANNEL=latest$/m);
  assert.match(a, /^NX_FIVEM_BUILD=$/m);
  const pinned = renderArtifactEnv(fivemSettingsFrom({ artifactBuild: "35245" }));
  assert.match(pinned, /^NX_FIVEM_BUILD=35245$/m);
  assert.match(pinned, /^NX_FIVEM_SHA256=16fcffd5/m);
  assert.match(renderArtifactEnv(fivemSettingsFrom({ artifactBuild: "99999" })), /^NX_FIVEM_BUILD=$/m, "unknown builds can't be pinned");
});

// --------------------------------------------------------------------------- schema

test("schema: fivem validates, defaults are sane, bad values rejected", () => {
  assert.ok(schemaFor("fivem"));
  const ok = validateConfig("fivem", {});
  assert.ok(ok.ok);
  if (ok.ok) {
    assert.equal(ok.values.sv_licenseKey, "");
    assert.equal(ok.values.onesync, "on");
    assert.equal(ok.values.txadmin, false);
  }
  assert.equal(validateConfig("fivem", { sv_licenseKey: "not-a-key" }).ok, false);
  assert.equal(validateConfig("fivem", { sv_licenseKey: KEY }).ok, true);
  assert.equal(validateConfig("fivem", { sv_hostname: 'a";quit' }).ok, false);
  assert.equal(validateConfig("fivem", { resources: "a;b" }).ok, false);
  assert.equal(validateConfig("fivem", { steamWebApiKey: "nothex" }).ok, false);
  assert.equal(validateConfig("fivem", { sv_maxclients: 4000 }).ok, false);
  assert.equal(validateConfig("fivem", { artifactBuild: "12345" }).ok, false);
  assert.equal(validateConfig("fivem", { artifactBuild: "35245" }).ok, true);
});

// --------------------------------------------------------------------------- BYO key handling

test("prepareFivemConfig: key required to order, sealed, never left in plaintext", () => {
  const base = (validateConfig("fivem", {}) as { ok: true; values: Record<string, string | number | boolean> }).values;
  const noKey = prepareFivemConfig({ values: base, planSlots: 48, requireKey: true });
  assert.equal(noKey.ok, false);
  const withKey = prepareFivemConfig({ values: { ...base, sv_licenseKey: KEY }, planSlots: 48, requireKey: true });
  assert.ok(withKey.ok);
  if (!withKey.ok) return;
  assert.equal(withKey.values.sv_licenseKey, "");
  assert.ok(!JSON.stringify(withKey.values).includes(KEY), "plaintext key must not be in the persisted blob");
  assert.equal(fivemLicenseKey(withKey.values), KEY);
  // Settings save with a blank key keeps the stored one.
  const keep = prepareFivemConfig({ values: base, previous: withKey.values, planSlots: 48, requireKey: true });
  assert.ok(keep.ok && fivemLicenseKey(keep.values) === KEY);
  // Forged marker is "no key".
  const forged = prepareFivemConfig({ values: base, previous: { [FIVEM_LICENSE_MARKER]: "AAAA:BBBB:CCCC" }, planSlots: 48, requireKey: true });
  assert.equal(forged.ok, false);
  // Slot cap enforced.
  const tooMany = prepareFivemConfig({ values: { ...base, sv_licenseKey: KEY, sv_maxclients: 64 }, planSlots: 255, requireKey: true });
  assert.equal(tooMany.ok, false);
  // Preview mode does not encrypt.
  const preview = prepareFivemConfig({ values: { ...base, sv_licenseKey: KEY }, planSlots: 48, requireKey: true, seal: false });
  assert.ok(preview.ok && !(FIVEM_LICENSE_MARKER in preview.values));
});

test("sealFivemIntentConfig: a pasted key never leaves the form boundary in plaintext", () => {
  const sealed = sealFivemIntentConfig({ sv_licenseKey: KEY, sv_hostname: "x" })!;
  assert.equal(sealed.sv_licenseKey, "");
  assert.ok(!JSON.stringify(sealed).includes(KEY));
  assert.equal(fivemLicenseKey(sealed), KEY);
  const other = { MOTD: "hi" };
  assert.equal(sealFivemIntentConfig(other), other, "other families untouched");
  assert.ok(JSON.stringify(sealed).length < 480, "fits provider metadata");
});

test("derived secrets: stable per server, different across servers, alnum", () => {
  const a = deriveFivemSecrets("srv_a");
  assert.deepEqual(a, deriveFivemSecrets("srv_a"));
  assert.notEqual(a.rconPassword, deriveFivemSecrets("srv_b").rconPassword);
  assert.match(a.rconPassword, /^[A-Za-z0-9]{24}$/);
  assert.match(a.playersToken, /^[A-Za-z0-9]{32}$/);
});

// --------------------------------------------------------------------------- install script

test("generated shell scripts all pass bash -n", () => {
  for (const [name, s] of Object.entries({ NX_ARTIFACT_SH, NX_START_SH, NX_RESOURCES_SH, setup: fivemSetupScript() })) {
    const r = bashSyntaxOk(s);
    assert.ok(r.ok, `${name}: ${r.err}`);
  }
});

test("full provisioning pipeline: buildGameSetupScript renders files, wraps docker in fivem.service, txAdmin loopback-only", () => {
  const sealed = sealFivemIntentConfig({ sv_licenseKey: KEY })!;
  const gameConfig = { ...(validateConfig("fivem", { sv_hostname: "Nxeon Test RP", licenceTier: "aurum" }) as any).values, [FIVEM_LICENSE_MARKER]: sealed[FIVEM_LICENSE_MARKER] };
  const raw = fivemSetupScript();
  assert.ok(raw.includes(FIVEM_FILES_PLACEHOLDER));
  assert.ok(skipDockerInstallIfPresent(raw) !== raw, "docker install prefix is the shape skipDockerInstallIfPresent expects");
  const out = buildGameSetupScript({ id: "srv_test", osTemplate: { setupScript: raw, family: "fivem" }, gameConfig, gamePlan: { ramMB: 8192, slots: 128 } })!;
  assert.ok(out);
  assert.ok(!out.includes(FIVEM_FILES_PLACEHOLDER));
  assert.match(out, /cat > \/etc\/systemd\/system\/fivem\.service/);
  assert.match(out, /docker create --name fivem /);
  assert.match(out, /-p 127\.0\.0\.1:40120:40120\/tcp/);
  assert.doesNotMatch(out, /-p 40120:40120/, "txAdmin never on a public interface");
  assert.match(out, /--user 30120:30120/);
  assert.doesNotMatch(out, /--restart/, "systemd owns restarts");
  // The key only exists inside the base64 of secrets.cfg, never as plain text.
  assert.ok(!out.includes(KEY), "plaintext key not visible in the script");
  const files = [...out.matchAll(/printf '%s' '([A-Za-z0-9+/=]+)' \| base64 -d > (\S+) && chmod (\d+)/g)].map((m) => ({ path: m[2], mode: m[3], body: Buffer.from(m[1], "base64").toString("utf8") }));
  const byPath = Object.fromEntries(files.map((f) => [f.path, f]));
  assert.ok(byPath["/opt/fivem/server-data/server.cfg"].body.includes('sv_hostname "Nxeon Test RP"'));
  assert.match(byPath["/opt/fivem/server-data/server.cfg"].body, /^sv_maxclients 32$/m);
  assert.equal(byPath["/opt/fivem/server-data/secrets.cfg"].mode, "0600");
  assert.ok(byPath["/opt/fivem/server-data/secrets.cfg"].body.includes(`sv_licenseKey "${KEY}"`));
  assert.ok(byPath["/opt/fivem/server-data/secrets.cfg"].body.includes(`rcon_password "${deriveFivemSecrets("srv_test").rconPassword}"`));
  assert.match(byPath["/opt/fivem/nx/runtime.env"].body, /TXHOST_MAX_SLOTS=128/);
  assert.equal(byPath["/opt/fivem/nx/nx-artifact.sh"].body, NX_ARTIFACT_SH);
  assert.ok(bashSyntaxOk(out).ok, bashSyntaxOk(out).err);
  // Reinstall/wipe helpers see the real container + data mounts.
  assert.equal(dockerContainerNameFrom(raw), "fivem");
  assert.deepEqual(dockerHostMountsFrom(raw), ["/opt/fivem/artifact", "/opt/fivem/server-data", "/opt/fivem/nx"]);
});

test("applyFivemSetup is a no-op for other families and for scripts without the placeholder", () => {
  const input = { gameConfig: {}, planSlots: 48, licenseKey: null, rconPassword: "x", playersToken: "y" };
  assert.equal(applyFivemSetup("docker run -d --name mc x", "minecraft", input), "docker run -d --name mc x");
  assert.equal(applyFivemSetup("no placeholder", "fivem", input), "no placeholder");
});

test("settings re-apply script: writes cfg files, never the installer scripts, valid bash", () => {
  const s = fivemApplyScript({ gameConfig: { sv_hostname: "Changed" }, planSlots: 48, licenseKey: KEY, ...deriveFivemSecrets("srv_test") });
  assert.ok(bashSyntaxOk(s).ok);
  assert.match(s, /server-data\/server\.cfg/);
  assert.doesNotMatch(s, /nx-artifact\.sh/);
  assert.match(s, /echo NXFC:OK$/);
});

// --------------------------------------------------------------------------- registry + update

test("registry: health port 30120/tcp, joins on tcp+udp 30120, control spec, update source", () => {
  assert.deepEqual(GAME_PORT.fivem, { port: 30120, protocol: "tcp" });
  assert.deepEqual(joinPortsFor("fivem"), [{ port: 30120, protocol: "tcp" }, { port: 30120, protocol: "udp" }]);
  const spec = controlSpec("fivem")!;
  assert.deepEqual(spec.serviceHints, ["fivem"]);
  assert.deepEqual(spec.dataRoots, ["/opt/fivem/server-data"]);
  assert.equal(updatesFromSteam("fivem"), true);
  const cmd = updateCommand("fivem");
  assert.match(cmd, /nx-artifact\.sh fetch/);
  assert.match(cmd, /NXGU:%s/);
  assert.ok(bashSyntaxOk(cmd).ok, bashSyntaxOk(cmd).err);
});

// --------------------------------------------------------------------------- probes

test("txAdmin PIN: parses the real line (captured from txAdmin v8.1.1/b35245, ANSI inverse)", () => {
  const real = "[17:47:26][tx] Server data will be saved in  /x/txData/default \n[17:47:27][tx:AdminStore] Use this PIN to add a new master account: \x1b[7m 6131 \x1b[27m\n";
  assert.equal(parseTxAdminPin(real), "6131");
  assert.equal(parseTxAdminPin(real + "[..] Use this PIN to add a new master account:  0042 \n"), "0042", "latest PIN wins");
  assert.equal(parseTxAdminPin("nothing here"), null);
  assert.equal(txAdminTunnelCommand("203.0.113.7", 22), "ssh -N -L 40120:127.0.0.1:40120 root@203.0.113.7");
  assert.equal(txAdminTunnelCommand("203.0.113.7", 20044), "ssh -N -L 40120:127.0.0.1:40120 -p 20044 root@203.0.113.7");
  assert.equal(txAdminTunnelCommand("a;rm -rf /", 22), "ssh -N -L 40120:127.0.0.1:40120 root@<server-ip>");
});

test("/info.json + /players.json parsing (shape per FXServer InfoHttpHandler; constructed sample — not captured live, no licensed server was run)", () => {
  const info = parseInfoJson(JSON.stringify({ enhancedHostSupport: true, resources: ["chat", "mapmanager"], server: "FXServer-master SERVER v1.0.0.35245 linux", vars: { sv_maxClients: "48", sv_projectName: "My RP", onesync_enabled: "true" }, version: 123 }));
  assert.deepEqual(info, { server: "FXServer-master SERVER v1.0.0.35245 linux", build: "35245", maxClients: 48, hostname: "My RP", resources: 2, onesync: "true" });
  assert.equal(parseInfoJson("<html>nginx</html>"), null);
  assert.equal(parseInfoJson({ server: "Apache" }), null);
  const players = parsePlayersJson('[{"id":1,"name":"Alice","ping":40,"identifiers":[]},{"id":2,"ping":55}]');
  assert.deepEqual(players, [{ id: 1, name: "Alice", ping: 40 }, { id: 2, name: null, ping: 55 }]);
  assert.equal(parsePlayersJson("{}"), null);
});

// --------------------------------------------------------------------------- the installer against the REAL artifact (opt-in)

test("nx-artifact.sh install against the real build-35245 archive (opt-in: FIVEM_ARTIFACT_FILE=/path/fx.tar.xz)", { skip: !process.env.FIVEM_ARTIFACT_FILE }, () => {
  const file = process.env.FIVEM_ARTIFACT_FILE!;
  const root = mkdtempSync(join(tmpdir(), "nxfivem-"));
  try {
    mkdirSync(join(root, "nx"), { recursive: true });
    mkdirSync(join(root, "bin"));
    writeFileSync(join(root, "nx", "nx-artifact.sh"), NX_ARTIFACT_SH);
    writeFileSync(join(root, "nx", "artifact.env"), renderArtifactEnv(fivemSettingsFrom({ artifactBuild: "35245" })));
    const size = readFileSync(file).length;
    // curl shim: HEAD → content-length, GET -o → copy the local archive. No network.
    writeFileSync(
      join(root, "bin", "curl"),
      `#!/bin/bash\nout=""; head=0\nwhile [ $# -gt 0 ]; do case "$1" in -o) out="$2"; shift;; -fsSI) head=1;; esac; shift; done\nif [ $head = 1 ]; then printf 'HTTP/2 200\\r\\ncontent-length: ${size}\\r\\n\\r\\n'; exit 0; fi\ncp '${file}' "$out"\n`
    );
    chmodSync(join(root, "bin", "curl"), 0o755);
    const env = { ...process.env, PATH: `${join(root, "bin")}:${process.env.PATH}`, NX_FIVEM_ROOT: root };
    const r = spawnSync("bash", [join(root, "nx", "nx-artifact.sh"), "install"], { env, encoding: "utf8" });
    assert.equal(r.status, 0, r.stdout + r.stderr);
    assert.match(r.stdout, /NXFA:SHA256:16fcffd53a30a3909cbb2cfd26f89f950a59452792cafd0eda2174bdfeef9b2f/);
    assert.match(r.stdout, /NXFA:SWAPPED:35245/);
    assert.ok(existsSync(join(root, "artifact", "run.sh")));
    assert.ok(existsSync(join(root, "artifact", "alpine", "opt", "cfx-server", "FXServer")));
    // Second run: already current, nothing downloaded or swapped.
    const again = spawnSync("bash", [join(root, "nx", "nx-artifact.sh"), "fetch"], { env, encoding: "utf8" });
    assert.match(again.stdout, /NXFA:CURRENT:35245/);
    // A tampered checksum is refused.
    writeFileSync(join(root, "nx", "artifact.env"), renderArtifactEnv(fivemSettingsFrom({ artifactBuild: "35245" })).replace(/NX_FIVEM_SHA256=\w+/, "NX_FIVEM_SHA256=" + "0".repeat(64)));
    rmSync(join(root, "artifact"), { recursive: true });
    const bad = spawnSync("bash", [join(root, "nx", "nx-artifact.sh"), "install"], { env, encoding: "utf8" });
    assert.notEqual(bad.status, 0);
    assert.match(bad.stdout, /NXFA:ERR:sha256 mismatch/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

